list_payment_gateways.code:
import (
	"fmt"
)

resp, err := client.PaymentGateways().ListPaymentGateways(ctx, map[string]any{"limit": 20, "offset": 0, "promotional": "false"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["payment_gateways"].([]any) {
	gateway := row.(map[string]any)
	fmt.Println(gateway["id"], gateway["code"], gateway["name"], gateway["enabled"], gateway["default"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

